import logging
HINT_THERMAL = "\nSee the 'verify_heater' section in docs/Config_Reference.md\nfor the parameters that control this check.\n"

class HeaterCheck:

    def __init__(self, config):
        self.printer = config.get_printer()
        self.printer.register_event_handler("klippy:connect", self.handle_connect)
        self.printer.register_event_handler("klippy:shutdown", self.handle_shutdown)
        self.heater_name = config.get_name().split()[1]
        self.heater = None
        self.hysteresis = config.getfloat("hysteresis", 5.0, minval=0.0)
        self.max_error = config.getfloat("max_error", 120.0, minval=0.0)
        self.heating_gain = config.getfloat("heating_gain", 2.0, above=0.0)
        self.max_quick_error_count = config.getint("max_quick_error_count", 3, minval=0)
        self.check_quick_error_count = 0
        self.max_0_error_count = config.getint("max_0_error_count", 3, minval=0)
        self.check_0_error_count = 0
        default_gain_time = 20.0
        if self.heater_name == "heater_bed":
            default_gain_time = 60.0
        self.check_gain_time = config.getfloat("check_gain_time",
          default_gain_time, minval=1.0)
        self.approaching_target = self.starting_approach = False
        self.last_target = self.goal_temp = self.error = 0.0
        self.goal_systime = self.printer.get_reactor().NEVER
        self.check_timer = None

    def handle_connect(self):
        if self.printer.get_start_args().get("debugoutput") is not None:
            return
        pheaters = self.printer.lookup_object("heaters")
        self.heater = pheaters.lookup_heater(self.heater_name)
        logging.info("Starting heater checks for %s", self.heater_name)
        reactor = self.printer.get_reactor()
        self.check_timer = reactor.register_timer(self.check_event, reactor.NOW)

    def handle_shutdown(self):
        if self.check_timer is not None:
            reactor = self.printer.get_reactor()
            reactor.update_timer(self.check_timer, reactor.NEVER)

    def check_event(self, eventtime):
        temp, target = self.heater.get_temp(eventtime)
        if temp >= target - self.hysteresis or target <= 0.0:
            if self.approaching_target:
                if target:
                    logging.info("Heater %s within range of %.3f", self.heater_name, target)
                self.approaching_target = self.starting_approach = False
                if temp <= target + self.hysteresis:
                    self.error = 0.0
                    self.check_quick_error_count = 0
                self.last_target = target
                return eventtime + 1.0
            if abs(target - temp) >= self.max_error:
                logging.info(f'{self.check_quick_error_count}th {self.heater_name} Heater temp is {temp} target is {target}, {"will check again" if self.check_quick_error_count < self.max_quick_error_count else "will check error"}')
                self.check_quick_error_count += 1
                if self.check_quick_error_count < self.max_quick_error_count:
                    return eventtime + 1.0
            else:
                self.check_quick_error_count = 0
            if temp == 0:
                logging.info(f'{self.check_0_error_count}th {self.heater_name} Heater temp is {temp} target is {target}, {"will check again" if self.check_0_error_count < self.max_0_error_count else "will check error"}')
                self.check_0_error_count += 1
                if self.check_0_error_count < self.max_0_error_count:
                    return eventtime + 1.0
            else:
                self.check_0_error_count = 0
            self.error += target - self.hysteresis - temp
            if abs(temp - target) <= self.hysteresis:
                self.error = 0.0
                self.check_quick_error_count = 0
                self.check_0_error_count = 0
            if not self.approaching_target:
                if target != self.last_target:
                    logging.info("Heater %s approaching new target of %.3f", self.heater_name, target)
                    self.approaching_target = self.starting_approach = True
                    self.goal_temp = temp + self.heating_gain
                    self.goal_systime = eventtime + self.check_gain_time
                    self.check_quick_error_count = 0
                    self.check_0_error_count = 0
                else:
                    if self.error >= self.max_error:
                        self.check_quick_error_count = 0
                        logging.error(f"verify_heater fault {self.heater_name} target: {target} temp:{temp} error:{self.error} max_error={self.max_error} ")
                        if ":" in self.heater.heater_pin:
                            mcu_name = self.heater.heater_pin.split(":")[0]
                            try:
                                serial = self.printer.lookup_object(f"mcu {mcu_name}")._clocksync.serial
                                params = serial.send_with_response("get_clock", "clock")
                                clock = params["clock"]
                                sent_time = params["#sent_time"]
                                receive_time = params["#receive_time"]
                                logging.info(f"creality:_is_active_mcu serial={serial.warn_prefix} clock={clock} sent_time={sent_time} receive_time={receive_time}")
                            except Exception as e:
                                try:
                                    logging.exception(e)
                                    logging.error(f"mcu {mcu_name} _is_active_mcu failed")
                                finally:
                                    e = None
                                    del e

                        return self.heater_fault()
            elif temp >= self.goal_temp:
                self.starting_approach = False
                self.error = 0.0
                self.check_quick_error_count = 0
                self.check_0_error_count = 0
                self.goal_temp = temp + self.heating_gain
                self.goal_systime = eventtime + self.check_gain_time
            elif eventtime >= self.goal_systime:
                self.approaching_target = False
                logging.info("Heater %s no longer approaching target %.3f", self.heater_name, target)
            elif self.starting_approach:
                self.goal_temp = min(self.goal_temp, temp + self.heating_gain)
            self.last_target = target
            return eventtime + 1.0

    def heater_fault(self):
        msg = "Heater %s not heating at expected rate" % (self.heater_name,)
        logging.error(msg)
        self.printer.invoke_shutdown(msg + HINT_THERMAL)
        return self.printer.get_reactor().NEVER


def load_config_prefix(config):
    return HeaterCheck(config)

